import React, { createContext, useState, useContext } from 'react';
import api from '../api/axios';

const AuthContext = createContext();

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);

  const login = async (emailOrUser, passwordOrToken) => {
  // Si on passe directement un user et un token (après changement mdp)
  if (typeof emailOrUser === 'object') {
    setUser(emailOrUser);
    localStorage.setItem('user', JSON.stringify(emailOrUser));
    return;
  }
  // Sinon login normal
  const res = await api.post('/login', { email: emailOrUser, mot_de_passe: passwordOrToken });
  setUser(res.data.user);
  localStorage.setItem('token', res.data.token);
  localStorage.setItem('user', JSON.stringify(res.data.user));
};


  const logout = async () => {
  try {
    await api.post('/logout');
  } catch(e) {
    // ignore — on déconnecte quand même
  } finally {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    localStorage.removeItem('lastActivity');
    localStorage.removeItem('activePage');
    setUser(null);
  }
};

  return (
    <AuthContext.Provider value={{ user, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  return useContext(AuthContext);
}
